using System; using DiceCraft.Core;
namespace UnityEngine { public static class Application { public static string dataPath => System.IO.Path.GetFullPath("DicePrototype/Assets"); } public static class JsonUtility { public static T FromJson<T>(string json) => System.Text.Json.JsonSerializer.Deserialize<T>(json,new System.Text.Json.JsonSerializerOptions{IncludeFields=true}); } }
namespace UnityEngine.UI { public class Button { public StubGameObject gameObject; public string name; public StubEvent onClick; } public class StubGameObject { public bool activeInHierarchy; } public class StubEvent { public void Invoke()=>throw new NotSupportedException(); } }
namespace DiceCraft { public class GameApp { public bool IsBusy; public GameSession Session; public GameConfig Config; public StubCanvas canvas; public bool UnlockDebug(string value)=>throw new NotSupportedException(); public bool EnterDebugWorkspace()=>throw new NotSupportedException(); public CommandResult Send(SessionCommand command)=>throw new NotSupportedException(); } public class StubCanvas { public T[] GetComponentsInChildren<T>(bool includeInactive)=>throw new NotSupportedException(); } }
internal static class FixturePreflight { static int Main() { var cfg=UnityEngine.JsonUtility.FromJson<GameConfig>(GameConfig.PrepareJsonForUnity(System.IO.File.ReadAllText("DicePrototype/Assets/Game/Data/P0Config.json")));cfg.Validate();int count=0;foreach(DiceCraft.Verification.Art07FixtureKind kind in Enum.GetValues(typeof(DiceCraft.Verification.Art07FixtureKind))) { var session=GameSession.CreateDebugWorkspace(cfg,new MemorySaveStore());var fixture=DiceCraft.Verification.Art07Fixtures.Create(cfg,kind);var r=session.Execute(new SessionCommand { commandId="fixture",expectedActionSequence=0,kind=CommandKind.ApplyDebugScene,debugScene=fixture });if(!r.accepted)throw new Exception(kind+": "+r.error);DiceCraft.Verification.Art07Fixtures.Verify(kind,session.State,session.PreviewScoreRange());Console.WriteLine(kind+" real Session passed; preview="+session.PreviewScoreRange()?.minimum.score);count++; } Console.WriteLine(count+" fixture Create/real Session checks passed; GameApp/UI not executed by this managed preflight.");return 0;} }
